/* eslint-disable @typescript-eslint/no-require-imports -- loaded by jest.setup.js and the CommonJS tooling */
'use strict';

/**
 * Loads `@testing-library/jest-dom` for a test file, or skips it.
 *
 * Importing jest-dom costs about 0.11 s per test file (the module graph is
 * re-evaluated for every file), and about three test files in four never call
 * one of its matchers. `no-jest-dom-tests.json` lists the test files whose
 * import closure names none of them (generated by scripts/jest/jest-dom-usage.js
 * from the same static closure the result cache uses).
 *
 * Fail safe, in this order:
 *   1. A test file that is not on the list gets jest-dom, exactly as before.
 *   2. A listed file gets a THROWING stub for every jest-dom matcher instead,
 *      so using one (also through `.not`) fails the test loudly with a message
 *      that names the list; it can never pass without having run the matcher.
 *   3. The path is compared as written by Jest; anything that does not match
 *      (another checkout root, a symlinked path) simply loads jest-dom.
 */

const path = require('node:path');

const ROOT = path.resolve(__dirname, '..', '..');

// Every matcher @testing-library/jest-dom registers, including deprecated
// aliases. scripts/__tests__/jest-dom-skip.test.ts checks this against the
// installed package so a new jest-dom release cannot add one unnoticed.
const JEST_DOM_MATCHERS = [
  'toBeDisabled',
  'toBeEnabled',
  'toBeEmpty',
  'toBeEmptyDOMElement',
  'toBeInTheDocument',
  'toBeInTheDOM',
  'toBeInvalid',
  'toBeRequired',
  'toBeValid',
  'toBeVisible',
  'toContainElement',
  'toContainHTML',
  'toHaveAccessibleDescription',
  'toHaveAccessibleErrorMessage',
  'toHaveAccessibleName',
  'toHaveAttribute',
  'toHaveClass',
  'toHaveFocus',
  'toHaveFormValues',
  'toHaveStyle',
  'toHaveTextContent',
  'toHaveValue',
  'toHaveDisplayValue',
  'toBeChecked',
  'toBePartiallyChecked',
  'toHaveRole',
  'toHaveSelection',
  'toHaveErrorMessage',
  'toHaveDescription',
];

let skipSet;
function skipSetOf() {
  skipSet ??= new Set(require('./no-jest-dom-tests.json'));
  return skipSet;
}

/** Repo-relative posix path of `testPath`, or null when it is outside the repo. */
function relativeTestPath(testPath) {
  if (typeof testPath !== 'string') return null;
  const relative = path.relative(ROOT, testPath);
  if (relative === '' || relative.startsWith('..') || path.isAbsolute(relative))
    return null;
  return relative.split(path.sep).join('/');
}

function skipsJestDom(testPath) {
  const relative = relativeTestPath(testPath);
  return relative !== null && skipSetOf().has(relative);
}

/** Matchers that fail the test instead of running, for a file that skipped jest-dom. */
function jestDomStubs(testPath) {
  const where = relativeTestPath(testPath) ?? String(testPath);
  return Object.fromEntries(
    JEST_DOM_MATCHERS.map((name) => [
      name,
      function jestDomNotLoaded() {
        throw new Error(
          `${name} is a @testing-library/jest-dom matcher, but ${where} is listed in ` +
            'config/jest/no-jest-dom-tests.json, so jest-dom was not loaded for it. ' +
            'Remove it from the list (regenerate: node scripts/jest/jest-dom-usage.js --write) ' +
            'or import @testing-library/jest-dom in the test.',
        );
      },
    ]),
  );
}

/**
 * @param {{ extend: (matchers: object) => void }} expectApi Jest's `expect`
 * @param {string} testPath the running test file (expect.getState().testPath)
 * @param {() => void} loadJestDom `() => require('@testing-library/jest-dom')`
 */
function setUpJestDom(expectApi, testPath, loadJestDom) {
  if (!skipsJestDom(testPath)) return loadJestDom();
  expectApi.extend(jestDomStubs(testPath));
  // jest-dom's only global side effect besides `expect.extend`: it requires the `css.escape`
  // polyfill, which defines `window.CSS.escape`. user-event calls it (radio-group keyboard
  // navigation), so a file that skips jest-dom still needs it. A string literal on purpose:
  // the result-cache keyer treats any require(<expression>) in the setup closure as a dynamic
  // load and then keys every test file on the whole repo.
  require('css.escape');
}

module.exports = {
  JEST_DOM_MATCHERS,
  jestDomStubs,
  relativeTestPath,
  setUpJestDom,
  skipsJestDom,
};
